'use client';
import Link from 'next/link';
import VendorShell from '../../../components/VendorShell';
import { useEffect, useMemo, useState } from 'react';
import { api, patch, post } from '../../../lib/api';

type VendorCategory={id:string;name:string;imageUrl?:string|null;displayOrder:number;isActive:boolean;availabilityStartTime?:string|null;availabilityEndTime?:string|null;_count?:{products:number}};

export default function CategoriesPage(){
 const [categories,setCategories]=useState<VendorCategory[]>([]),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[error,setError]=useState(''),[success,setSuccess]=useState(''),[search,setSearch]=useState(''),[filter,setFilter]=useState<'all'|'active'|'hidden'>('all'),[editing,setEditing]=useState<VendorCategory|null>(null),[showForm,setShowForm]=useState(false),[name,setName]=useState(''),[imageUrl,setImageUrl]=useState(''),[startTime,setStartTime]=useState(''),[endTime,setEndTime]=useState('');
 async function load(){try{setLoading(true);setError('');const data=await api<VendorCategory[]>('/api/vendor/categories');setCategories(Array.isArray(data)?data:[]);}catch(e:any){setError(e?.message||'Failed to load your categories.')}finally{setLoading(false)}}
 useEffect(()=>{load()},[]);
 const visible=useMemo(()=>categories.filter(c=>c.name.toLowerCase().includes(search.trim().toLowerCase())&&(filter==='all'||(filter==='active'?c.isActive:!c.isActive))),[categories,search,filter]);
 function reset(){setName('');setImageUrl('');setStartTime('');setEndTime('');setEditing(null)}
 function create(){reset();setShowForm(true)}
 function edit(c:VendorCategory){setEditing(c);setName(c.name);setImageUrl(c.imageUrl||'');setStartTime(c.availabilityStartTime||'');setEndTime(c.availabilityEndTime||'');setShowForm(true)}
 async function save(){if(!name.trim()){setError('Give the category a name.');return}if((startTime&&!endTime)||(!startTime&&endTime)){setError('Set both start and end times, or leave both blank.');return}try{setSaving(true);setError('');setSuccess('');const body={name:name.trim(),imageUrl:imageUrl.trim()||undefined,availabilityStartTime:startTime||undefined,availabilityEndTime:endTime||undefined};if(editing)await patch(`/api/vendor/categories/${editing.id}`,body);else await post('/api/vendor/categories',body);setShowForm(false);reset();await load();setSuccess(editing?'Category updated.':'Category created.')}catch(e:any){setError(e?.message||'Could not save category.')}finally{setSaving(false)}}
 async function toggle(c:VendorCategory){try{setError('');setSuccess('');await post(`/api/vendor/categories/${c.id}/${c.isActive?'deactivate':'activate'}`);await load();setSuccess(c.isActive?'Category hidden from your catalogue.':'Category is active again.')}catch(e:any){setError(e?.message||'Could not update category.')}}
 async function move(c:VendorCategory,d:-1|1){const index=categories.findIndex(x=>x.id===c.id),target=index+d;if(index<0||target<0||target>=categories.length)return;const next=[...categories];[next[index],next[target]]=[next[target],next[index]];try{setSaving(true);setError('');setSuccess('');await post('/api/vendor/categories/reorder',{categoryIds:next.map(x=>x.id)});setCategories(next.map((x,i)=>({...x,displayOrder:i})));setSuccess('Category order saved.')}catch(e:any){setError(e?.message||'Could not save category order.')}finally{setSaving(false)}}
 const active=categories.filter(c=>c.isActive).length,hidden=categories.length-active,products=categories.reduce((n,c)=>n+(c._count?.products||0),0);
 return <VendorShell><div className="category-page">
  <section className="page-heading-row"><div><p className="eyebrow">CATALOG / CATEGORIES</p><h1>Categories</h1><p className="page-subtitle">Organize your catalogue into clear sections customers can browse.</p></div><button className="btn primary" onClick={create}>＋ Create category</button></section>
  {error&&<div className="error category-alert">{error}</div>}{success&&<div className="success-banner">{success}</div>}
  <section className="category-metrics"><div><span>Total categories</span><strong>{categories.length}</strong></div><div><span>Active</span><strong>{active}</strong></div><div><span>Hidden</span><strong>{hidden}</strong></div><div><span>Products organized</span><strong>{products}</strong></div></section>
  <section className="category-card"><div className="category-toolbar"><div className="category-tabs">{(['all','active','hidden'] as const).map(x=><button key={x} className={`catalog-tab ${filter===x?'active':''}`} onClick={()=>setFilter(x)}>{x==='all'?`All ${categories.length}`:x==='active'?`Active ${active}`:`Hidden ${hidden}`}</button>)}</div><label className="category-search">⌕<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search categories..."/></label></div>
   {loading?<div className="category-state"><span className="spinner"/><p>Loading your categories…</p></div>:visible.length===0?<div className="category-state"><div className="state-icon">▦</div><h3>{categories.length?'No matching categories':'Create your first category'}</h3><p>{categories.length?'Try a different search or filter.':'Use categories such as Rice, Drinks, Snacks or Accessories to organize your store.'}</p>{!categories.length&&<button className="btn primary" onClick={create}>Create category</button>}</div>:<div className="category-list">{visible.map(c=><article className={`category-row ${!c.isActive?'is-hidden':''}`} key={c.id}><div className="category-drag">⋮⋮</div><div className="category-image">{c.imageUrl?<img src={c.imageUrl} alt=""/>:<span>{c.name.charAt(0).toUpperCase()}</span>}</div><div className="category-info"><strong>{c.name}</strong><span>{c._count?.products||0} product{c._count?.products===1?'':'s'}{c.availabilityStartTime&&c.availabilityEndTime?` · ${c.availabilityStartTime}–${c.availabilityEndTime}`:''}</span></div><span className={`status-badge ${c.isActive?'status-active':'status-hidden'}`}>{c.isActive?'Active':'Hidden'}</span><div className="category-actions"><button disabled={saving||categories.indexOf(c)===0} onClick={()=>move(c,-1)}>↑</button><button disabled={saving||categories.indexOf(c)===categories.length-1} onClick={()=>move(c,1)}>↓</button><button onClick={()=>edit(c)}>Edit</button><button onClick={()=>toggle(c)}>{c.isActive?'Hide':'Activate'}</button></div></article>)}</div>}
  </section>
  <section className="category-guidance"><div className="state-icon">i</div><div><strong>Vendor categories are yours to organize</strong><p>ROZZI's global marketplace categories remain platform-controlled. These categories organize your own catalogue without changing the marketplace taxonomy.</p></div><Link href="/products">View products →</Link></section>
  {showForm&&<div className="modal-backdrop" onMouseDown={e=>{if(e.currentTarget===e.target){setShowForm(false);reset()}}}><section className="small-modal category-modal"><button className="drawer-close modal-x" onClick={()=>{setShowForm(false);reset()}}>×</button><p className="eyebrow">CATALOG CATEGORY</p><h2>{editing?'Edit category':'Create category'}</h2><p className="muted">Keep category names short and easy for customers to scan.</p><label className="modal-field">Category name<input className="input" autoFocus maxLength={80} value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Rice & Meals"/></label><label className="modal-field">Image URL <span className="field-optional">Optional</span><input className="input" value={imageUrl} onChange={e=>setImageUrl(e.target.value)} placeholder="https://…"/></label><div className="modal-time-grid"><label className="modal-field">Available from<input className="input" type="time" value={startTime} onChange={e=>setStartTime(e.target.value)}/></label><label className="modal-field">Available until<input className="input" type="time" value={endTime} onChange={e=>setEndTime(e.target.value)}/></label></div><p className="stock-help">Optional daily availability window. Leave both blank to keep the category available whenever your store is open.</p><div className="modal-actions"><button className="btn secondary" onClick={()=>{setShowForm(false);reset()}}>Cancel</button><button className="btn primary" disabled={saving} onClick={save}>{saving?'Saving…':editing?'Save changes':'Create category'}</button></div></section></div>}
 </div></VendorShell>
}
